import type { Metadata } from 'next'
import { ViewTransition } from 'react'
import { pageSlide } from '@/lib/view-transitions'
import './globals.css'

export const metadata: Metadata = {
  title: 'Product Gallery',
  description: 'A simple product gallery',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body>
        {/*
          The layout survives navigation, so React sees a swapped `children` as
          an update to this one transition: the outgoing page is snapshotted
          alongside the incoming one and the two slide past each other.

          Anything further down the tree with its own <ViewTransition> (the
          product images, the Suspense boundaries) is captured as a separate
          group and animates on its own — that's what lets the product image
          morph while the page around it slides.
        */}
        <ViewTransition default={pageSlide}>{children}</ViewTransition>
      </body>
    </html>
  )
}

