import Link from 'next/link'
import { ViewTransition } from 'react'
import { products } from '@/lib/products'
import { NAV_FORWARD, pageSlide, productImageName } from '@/lib/view-transitions'

export function ProductGrid() {
  return (
    <div className="product-grid">
      {products.map((product) => (
        <Link
          key={product.slug}
          href={`/product/${product.slug}`}
          className="product-card"
          transitionTypes={NAV_FORWARD}
        >
          {/*
            `name` matches the hero on this product's detail page, so React
            treats the two as one element and hands the browser a single group
            to morph between the thumbnail box and the hero box (`share`).

            The other three thumbnails have no counterpart on the detail page,
            so they get `exit` instead — and we give that the same class as the
            page slide so they travel with the page rather than fading in place.
          */}
          <ViewTransition
            name={productImageName(product.slug)}
            share="vt-morph"
            enter={pageSlide}
            exit={pageSlide}
          >
            <div
              className="product-image"
              style={{ backgroundColor: product.color }}
            />
          </ViewTransition>
          <h2>{product.name}</h2>
          <p>${product.price}</p>
        </Link>
      ))}
    </div>
  )
}

