@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ── View transitions ─────────────────────────────────────────────────────
 *
 * React assigns these class names via the `default`/`enter`/`exit`/`share`/
 * `update` props on <ViewTransition>, which land on the elements as the
 * `view-transition-class` CSS property. That's what `*.vt-name` matches below:
 * one rule can style every group sharing a class, which matters here because
 * the page and each product image are separate groups that need to move
 * together.
 */

:root {
  --vt-duration: 320ms;
  --vt-morph-duration: 420ms;
  --vt-reveal-duration: 260ms;
  --vt-ease: cubic-bezier(0.32, 0.72, 0, 1);
  /* Absolute, not a percentage: the page snapshot and each image snapshot are
     separate groups, and a percentage would resolve against each group's own
     box — the images would drift at a different speed from the page. */
  --vt-slide: 3rem;
}

@keyframes vt-fade-in {
  from {
    opacity: 0;
  }
}

@keyframes vt-fade-out {
  to {
    opacity: 0;
  }
}

/* `translate` rather than `transform`, which the browser is already using to
   animate each group's position and size. */
@keyframes vt-slide-in-from-end {
  from {
    opacity: 0;
    translate: var(--vt-slide) 0;
  }
}

@keyframes vt-slide-out-to-start {
  to {
    opacity: 0;
