+::view-transition-group(*.vt-nav-back),
+::view-transition-group(*.vt-nav-neutral) {
+  animation-duration: var(--vt-duration);
+  animation-timing-function: var(--vt-ease);
+  z-index: 1;
+}
+
+/* Forward (grid → detail): the page we're leaving exits toward the start edge,
+   the page we're opening arrives from the end edge. */
+::view-transition-old(*.vt-nav-forward) {
+  animation: vt-slide-out-to-start var(--vt-duration) var(--vt-ease) both;
+  mix-blend-mode: normal;
+}
+
+::view-transition-new(*.vt-nav-forward) {
+  animation: vt-slide-in-from-end var(--vt-duration) var(--vt-ease) both;
+  mix-blend-mode: normal;
+}
+
+/* Back (detail → grid): mirrored, so the gesture reads as retracing a step. */
+::view-transition-old(*.vt-nav-back) {
+  animation: vt-slide-out-to-end var(--vt-duration) var(--vt-ease) both;
+  mix-blend-mode: normal;
+}
+
+::view-transition-new(*.vt-nav-back) {
+  animation: vt-slide-in-from-start var(--vt-duration) var(--vt-ease) both;
+  mix-blend-mode: normal;
+}
+
+/* Navigations that carry no direction (browser back/forward). */
+::view-transition-old(*.vt-nav-neutral) {
+  animation: vt-fade-out var(--vt-duration) var(--vt-ease) both;
+}
+
+::view-transition-new(*.vt-nav-neutral) {
+  animation: vt-fade-in var(--vt-duration) var(--vt-ease) both;
+}
+
+/* Thumbnail ↔ hero. The browser interpolates the box; stretching both
+   snapshots to fill it keeps the 4:3 thumbnail and the 1:1 hero aligned on the
+   way through instead of letterboxing at their captured sizes. Runs above the
+   page slide so the image stays visible while the page moves under it. */
+::view-transition-group(*.vt-morph) {
+  animation-duration: var(--vt-morph-duration);
+  animation-timing-function: var(--vt-ease);
+  z-index: 3;
+}
+
+::view-transition-old(*.vt-morph),
+::view-transition-new(*.vt-morph) {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+  animation-duration: var(--vt-morph-duration);
+  animation-timing-function: var(--vt-ease);
+}
+
+/* Suspense fallback → content. Keeping the browser's own cross-fade (with
+   linear timing, which is what makes its `plus-lighter` blend seamless) and
+   letting the group animate the height change between skeleton and copy. */
+::view-transition-group(*.vt-reveal) {
+  animation-duration: var(--vt-reveal-duration);
+  animation-timing-function: var(--vt-ease);
+  z-index: 2;
+}
+
+::view-transition-old(*.vt-reveal),
+::view-transition-new(*.vt-reveal) {
+  animation-duration: var(--vt-reveal-duration);
+  animation-timing-function: linear;
+}
+
+/* The `root` group is whatever isn't claimed by a <ViewTransition> above —
+   here just the page background, identical on both pages. Nothing to do but
+   keep it on the same clock as the page slide. */
+::view-transition-group(root),
+::view-transition-old(root),
+::view-transition-new(root) {
+  animation-duration: var(--vt-duration);
+}
+
+/* Reduced motion: nothing travels and nothing resizes visibly. Group geometry
+   snaps to its final value, and every group — including ones whose rules above
+   we're overriding — settles with a plain opacity cross-fade. Applied with `*`
+   so it also covers the browser's default animations on groups we never
+   named. */
+@media (prefers-reduced-motion: reduce) {
+  ::view-transition-group(*) {
+    animation-duration: 1ms !important;
+    animation-delay: 0ms !important;
+  }
+
+  /* Back to the browser's blend mode: the slides above opt out of it because
+     it brightens where two eased fades overlap, but these fades are linear,
+     which is the case it's designed for — the pair sums to opaque throughout. */
+  ::view-transition-old(*) {
+    animation: vt-fade-out 150ms linear both !important;
+    mix-blend-mode: plus-lighter !important;
+  }
+
+  ::view-transition-new(*) {
+    animation: vt-fade-in 150ms linear both !important;
+    mix-blend-mode: plus-lighter !important;
+  }
+
+  /* The skeletons keep their shape as the loading cue, minus the pulse. */
+  .skeleton-image,
+  .skeleton-text {
+    animation: none;
+  }
+}
